/* @lc app=leetcode id=2256 lang=kotlin */
class Solution { fun minimumAverageDifference(nums: IntArray): Int = nums.map { it.toLong() }.let { n -> n.fold(0L) { a, b -> a + b }.let { total -> n.indices.fold(Triple(0L, Long.MAX_VALUE, 0)) { acc, i -> (acc.first + n[i]).let { cur -> (Math.abs(cur / (i + 1) - (if (i == n.size - 1) 0L else (total - cur) / (n.size - i - 1)))).let { diff -> if (diff < acc.second) Triple(cur, diff, i) else Triple(cur, acc.second, acc.third) } } }.third } } }